texts['Readiness.modpack.target.mismatch'] = texts['PackTarget']
texts['Readiness.modpack.pending'] = texts['PackRecovery']
texts['Readiness.modpack.metadata.unknown'] = texts['PackInvalid']
assert all(len(v) == 8 for v in texts.values())
locale = root/'src/PTenoLauncher.Desktop/Localization'
cs = ['namespace PTenoLauncher.Desktop.Localization;', 'public static partial class TextCatalog', '{', '    private static void RegisterMrpackTexts()', '    {']
for k, v in texts.items():
    cs.append(f'        Texts[{json.dumps(k)}] = ({json.dumps(v[0],ensure_ascii=False)}, {json.dumps(v[1],ensure_ascii=False)});')
cs += ['    }','}']
(locale/'TextCatalog.Mrpack.cs').write_text('\n'.join(cs)+'\n',encoding='utf-8')
for i,code in enumerate(['uk','en','pl','de','es','fr','pt-BR','ru']):
    if i < 2:continue
    p=locale/'Locales'/f'{code}.json'; data=json.loads(p.read_text(encoding='utf-8-sig'));data.update({k:v[i] for k,v in texts.items()});p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'{len(texts)} mrpack keys generated for all eight languages.')
